import{_ as i,o as n,c as t,a2 as u}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Kamusi ya Neno","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0090-术语词典.md","filePath":"sw/0090-术语词典.md"}'),e={name:"sw/0090-术语词典.md"};function k(m,a,o,d,w,h){return n(),t("div",null,[...a[0]||(a[0]=[u('<h1 id="kamusi-ya-neno" tabindex="-1">Kamusi ya Neno <a class="header-anchor" href="#kamusi-ya-neno" aria-label="Permalink to &quot;Kamusi ya Neno&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>90</td></tr><tr><td>Moduli</td><td>Vifupi na Vifungu wa Rujia</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>kamusi ya neno, dhana ya msingi, ufafanuzi, neno zilizounganishwa, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-ufafanuzi-wa-neno" tabindex="-1">1. Ufafanuzi wa Neno <a class="header-anchor" href="#_1-ufafanuzi-wa-neno" aria-label="Permalink to &quot;1. Ufafanuzi wa Neno&quot;">​</a></h2><p>Kamusi hii inajumuisha maneno muhimu ya mfumo wa usanidi wa Ustaarabu wa Simbiozi ya Nanga, kwa lengo la kuunganisha matumizi ya neno katika hati zote na kuhakikisha uwiano na usahihi wa usemi wa dhana. Maneno yote yamepangwa kwa herufi ya kwanza ya pinyin ya Kichina, na kila neno lina jina la neno, jina la rujia la Kiingereza (kama ipo), ufafanuzi na maelezo mafupi. Kamusi hii ni hati ya sasisho la nguzo, na maneno mapya yanaendelea kuongezwa kadiri mfumo wa usanidi unavyo panuka.</p><h2 id="_2-jedwali-la-neno-la-msingi" tabindex="-1">2. Jedwali la Neno la Msingi <a class="header-anchor" href="#_2-jedwali-la-neno-la-msingi" aria-label="Permalink to &quot;2. Jedwali la Neno la Msingi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari</th><th>Neno</th><th>Ufafanuzi na Maelezo</th></tr></thead><tbody><tr><td>1</td><td>Nanga</td><td>Nod ya thabiti katika mtandao wa sheria, ni kiwango cha kuratibu cha kudumisha uthabiti wa sheria ya ndege, kutekeleza muunganisho wa kati ya ndege na kurudi nyuma kwa wakati. Nanga kwa asili ni mkusanyiko wa uzito mkubwa wa sheria ya asili ya ulimwengu katika eneo fulani la nafasi, ina uwezo wa kujitegemea na kalibrashoni.</td></tr><tr><td>2</td><td>Ustaarabu wa Simbiozi ya Nanga</td><td>Aina ya ustaarabu inayotumia mchakato wa nanga kama msingi wa kiufundi na mageuzi ya simbiozi kama dhana ya msingi. Inapinga mfumo wa mazoezi ya wanyama, na inashauri kurudisha haki ya kuchagua hatima na mageuzi kwa viumbe wote, na kutekeleza zaidi kazi zaidi faida, kuzalisha na kukua peke yao, kila mtu ana njia, kila jamaa inaendelea pamoja.</td></tr><tr><td>3</td><td>Hengyuanzhou</td><td>Kifupisho cha &quot;Wanling Hengmao Benyuan Zhou&quot;, ni ulimwengu wote ambao Ustaarabu wa Simbiozi ya Nanga unaishi na kutawala. Ni kiumbe cha muundo kinachojumuisha tabaka nne: ndege ya vifaa, tabaka la nishati, eneo la fahari, na mtandao wa sheria.</td></tr><tr><td>4</td><td>Wanling Hengmao Benyuan Zhou</td><td>Jina kamili la Hengyuanzhou. &quot;Wanling&quot; inamaanisha aina zote za uhai zenye uwezo wa fahamu na mageuzi, &quot;Hengmao&quot; inamaanisha mchakato wa nanga wa kudumisha usawa wa ulimwengu, &quot;Benyuan Zhou&quot; inasisitiza sifa ya msingi ya kuwa na sheria ya asili kama msingi na mageuzi ya simbiozi kama mwelekeo.</td></tr><tr><td>5</td><td>Simbiozi</td><td>Moja ya dhana za msingi za Ustaarabu wa Simbiozi ya Nanga, inamaanisha mageuzi ya pamoja yanayotimizwa kupitia ushirikiano wa manufaa kwa pande zote kati ya watu binafsi wa uhai, jamii, na ustaarabu tofauti, badala ya mageuzi ya wanyama kwa gharama ya wengine.</td></tr><tr><td>6</td><td>Mfumo wa Mazoezi ya Wanyama</td><td>Njia ya mazoezi inayotimizwa mageuzi yake mwenyewe kwa kumeza nishati, bahati, na hata asili ya wanyama. Aina ya mfumo ambayo Ustaarabu wa Simbiozi ya Nanga unapinga kwa nguvu, na inachukuliwa kuwa chanzo cha kuongezeka kwa kasi ya entropy ya ulimwengu na kukatika kwa mara kwa mara kwa ustaarabu.</td></tr><tr><td>7</td><td>Mia Tatu ya Mifumo ya Mazoezi ya Asili</td><td>Njia za mazoezi za halali zilizotolewa moja kwa moja kutoka sheria ya asili ya ulimwengu na zilizoithibitishwa na nanga, jumla mia tatu, zimegawanywa katika aina sita: aina ya tafsiri ya asili, aina ya mzunguko wa uhai, aina ya sheria ya nafasi, aina ya kuinua fahari, aina ya mtandao wa simbiozi, aina ya uhandisi wa matumizi, kila aina hamsini.</td></tr><tr><td>8</td><td>Misingi Mitatu ya Asili</td><td>Mifumo mitatu ya kwanza ya msingi kati ya mia tatu ya mifumo — Mfumo wa Kurudia Tafsiri (mfumo wa 1), Mfumo wa Mzunguko wa Uhai (mfumo wa 2), Mfumo wa Udhibiti wa Sheria ya Nafasi (mfumo wa 3), ambayo ni msingi wa mazoezi ya mifumo yote mingine.</td></tr><tr><td>9</td><td>Mfumo wa Kurudia Tafsiri</td><td>Mfumo wa 1 wa mazoezi ya asili, kwa sifa ya msingi ya kuongeza tafsiri ya mazoezi kwa mara mia, inatumia matumizi ya kiufundi ya Tunda la Kuzidisha kuinua uwezo wa tafsiri kwa mara mia, na inasisitiza uboreshaji wa njia ya mazoezi kupitia tafsiri, uthibitisho, na kurudia.</td></tr><tr><td>10</td><td>Mfumo wa Mzunguko wa Uhai</td><td>Mfumo wa 2 wa mazoezi ya asili, kwa msingi wa mzunguko mzuri wa nishati ya uhai, inasisitiza kuwa ubadilishaji wa nishati kati ya mtu anayefanya mazoezi mwenyewe na mazingira lazima uwe wa mzunguko, si wa wanyama.</td></tr><tr><td>11</td><td>Mfumo wa Udhibiti wa Sheria ya Nafasi</td><td>Mfumo wa 3 wa mazoezi ya asili, kwa msingi wa uelewa na udhibiti wa sheria ya nafasi, ni msingi wa mazoezi kwa matumizi muhimu kama vile mwingiliano wa kati ya ndege, ujenzi wa nafasi iliyotengwa, na teknolojia ya kioo cha nakala.</td></tr><tr><td>12</td><td>Tunda la Kuzidisha</td><td>Tunda la Kuzidisha lenye asili kutoka ulimwenguni wa One Piece, limetumika kiufundi katika Hengyuanzhou, na lina uwezo wa kuinua uwezo wa tafsiri wa mtu anayefanya mazoezi kwa mara mia, ni chombo cha msaada cha msingi cha Mfumo wa Kurudia Tafsiri. Moja ya buff za kwanza.</td></tr><tr><td>13</td><td>Mchakato wa Mkataba wa Uzalishaji Pamoja</td><td>Mchakato wa mgawanyo wa rasilimali wa Ustaarabu wa Simbiozi ya Nanga, ambao unagawanya rasilimali za mazoezi za ulimwengu kwa watu binafsi au vikundi kwa njia ya &quot;mkataba&quot;, na mkataba anapata haki ya matumizi ya rasilimali kupitia kazi na mchango, na kutekeleza zaidi kazi zaidi faida.</td></tr><tr><td>14</td><td>Mkakati wa Uanzishaji wa 20%</td><td>Lengo la mkakati wa hatua za Ustaarabu wa Simbiozi ya Nanga, awali anza asilimia 20 za viumbe vya ulimwengu wote kuwa watu wenye nguvu za juu zaidi za ndege, na kutumia kama mfupa kuendesha mageuzi ya pamoja ya asilimia 80 inayobaki.</td></tr><tr><td>15</td><td>Mtu Mwenye Nguvu za Juu zaidi za Ndege</td><td>Mtu mwenye nguvu ambaye amefikia kiwango cha juu sana cha mazoezi na ana uwezo wa kudumisha peke yake uthabiti wa sheria ya ndege moja. Ni kipokezi cha mafunzo cha lengo la Mkakati wa Uanzishaji wa 20%, na pia ni nguvu muhimu ya utunzaji wa mtandao wa nanga.</td></tr><tr><td>16</td><td>Mtandao wa Sheria</td><td>Tabaka ya nne ya muundo wa Hengyuanzhou, ni tabaka ya chini ya utekelezaji wa sheria ya asili ya ulimwengu na tabaka ya mzizi wa nanga. Mtandao wa sheria unapita ulimwengu wote, ni msingi wa kiufundi wa operesheni zote za sheria (ikiwa ni pamoja na udhibiti wa nafasi, kurudi nyuma kwa wakati, na ubadilishaji wa nishati).</td></tr><tr><td>17</td><td>Ndege</td><td>Eneo la uwepo lililobainishwa na seti ya sheria iliyo thabiti kiasi fulani, yenye kuendelea kwa nafasi-na-wakati huru. Kila ndege ina vigezo vya kawaida vya kimwili, uzito wa nishati, kasi ya mtiririko wa wakati, na uhai wa fahari.</td></tr><tr><td>18</td><td>Kizuizi cha Sheria</td><td>Kizuizi cha sheria kinachotenga ndege za jirani, nguvu yake inategemea kiwango cha tofauti ya vigezo vya sheria kati ya ndege za jirani. Kupita kwa ndege kunahitaji kushinda kizuizi cha sheria.</td></tr><tr><td>19</td><td>Alama ya Kidole cha Sheria</td><td>Kitambulisho cha kipekee kilichoundwa kwa hesabu ya hash ya vigezo vya sheria vya msingi vya kila ndege, urefu wake ni bit 128, na ni moja ya vigezo vya msingi vya mfumo wa kuratibu wa ndege.</td></tr><tr><td>20</td><td>Tazama Kwanza Kisha Uingilie Mdogo</td><td>Kanuni ya kwanza ya operesheni ya kurudi nyuma kwa wakati na uchunguzi wa kale wa kati ya ndege, inayodai kwamba kila kurudi nyuma au uchunguzi wa kale lazima kwanza kukamilisha hatua ya utunzaji safi, na baada ya kuhakikisha kuwa hakuna hatari kubwa tu ndio inaweza kufanya uingiliano mdogo.</td></tr><tr><td>21</td><td>Kioo cha Nakala</td><td>Kifaa cha nakala cha usahihi wa juu kinachotegemea sheria ya nafasi, chenye uwezo wa kufanya nakala kamili ya 1:1 kwa eneo lengwa bila kugusa kitu cha asili, ni kifaa cha msingi cha mpango wa uchunguzi wa kale wa mbali.</td></tr><tr><td>22</td><td>Nafasi Iliyotengwa</td><td>Eneo la sheria huru lililojengwa kupitia teknolojia ya udhibiti wa sheria ya nafasi, kinachotumika kubeba nakala za uchunguzi wa kale na kama mahali pa kazi kwa wafanyakazi wa uchunguzi wa kale, na limefungwa kabisa na ulimwengu wa nje na kizuizi cha sheria.</td></tr><tr><td>23</td><td>Rudisha Tu Maarifa</td><td>Kanuni ya msingi ya itifaki ya uchunguzi wa kale, inamaanisha kwamba kile kinachopatikana kutoka kwa kipengele cha lengwa wakati wa uchunguzi wa kale kinaweza kuwa tu maarifa na taarifa za abstract, na haifai kurudisha vifaa, nishati, au viumbe hai yoyote.</td></tr><tr><td>24</td><td>Kusafisha Taarifa</td><td>Mchakato wa kiufundi wa kuondoa kabisa alama za sheria za ndege ya chanzo zilizobebwa katika taarifa ya asili, na kubaki tu na maudhui ya maana safi, ni sehemu muhimu ya kuhakikisha usalama wa maarifa yanayorudishwa.</td></tr><tr><td>25</td><td>Paradoksi ya Wakati</td><td>Tukio la utata wa kimantiki katika mantiki ya sababu-na-matokeo unaosababishwa na tabia ya uingiliano wakati wa operesheni ya kurudi nyuma kwa wakati, ikiwa ni pamoja na aina nne kuu: paradoksi ya kuua babu, paradoksi ya taarifa, paradoksi ya uwepo, na paradoksi ya tukio.</td></tr><tr><td>26</td><td>Mnyororo wa Sababu-na-matokeo</td><td>Muundo wa mstari unaoendelea wa sababu za awali na matokeo ya baadaye kati ya matukio, ni dhana ya msingi ya sheria ya wakati. Hatari ya msingi ya operesheni ya kurudi nyuma kwa wakati ni usumbufu kwa mnyororo wa sababu-na-matokeo.</td></tr><tr><td>27</td><td>Katiba ya Simbiozi</td><td>Sera ya msingi ya Ustaarabu wa Simbiozi ya Nanga, yenye nguvu za kisheria za juu zaidi, na imeanzisha msingi wa ustaarabu wa kupinga wanyama na kushauri simbiozi pamoja na kanuni saba za msingi za katiba.</td></tr><tr><td>28</td><td>Usawa wa Kila Jamii</td><td>Moja ya kanuni saba za msingi za Katiba ya Simbiozi, inamaanisha kwamba aina zote za uhai, bila kujali jamii, kiwango cha mazoezi, au asili, zina sawa mbele ya sheria.</td></tr><tr><td>29</td><td>Uhai wa Aje</td><td>Aina ya uhai isiyofaa na ufafanuzi wa kawaida wa uhai na yenye aina ya uwepo maalum, inahitaji kutambuliwa na kusimamiwa kulingana na aina tatu za mchakato wa usimamizi wa kiwango.</td></tr><tr><td>30</td><td>Nishati ya Aje</td><td>Aina ya nishati isiyofaa na uainishaji wa kawaida wa nishati na yenye sifa na mifumo ya tabia maalum, inahitaji kuainishwa na kudhibitiwa kulingana na aina tatu za mchakato wa usimamizi wa kiwango.</td></tr><tr><td>31</td><td>Mwimbilizi wa Giza</td><td>Aina maalum ya uhai, inajumuisha masuala ya maadili ya kuishi pamoja kwa roho mbili, na inahitaji kusimamiwa kulingana na kanuni za maadili za roho mbili na aina nne za sheria za usimamizi wa matawi.</td></tr><tr><td>32</td><td>Maadili ya Roho Mbili</td><td>Kanuni za maadili kwa hali ya kuishi pamoja kwa roho mbili katika Mwimbilizi wa Giza, msingi ni kuheshimu haki za kila moja za roho mbili, na kukataza kuunganisha kwa kulazimisha au kuua moja ya pande.</td></tr><tr><td>33</td><td>Aina Tano za Uainishaji wa Ustaarabu wa Simbiozi</td><td>Aina tano za jamii za simbiozi zilizogawanywa kulingana na sifa za ustaarabu wa ulimwengu halisi: aina ya kuzingatia ya Mashariki ya Asia, aina ya ustawi ya Kaskazini mwa Ulaya, aina ya anuwai ya Kaskazini mwa Amerika, aina ya jamii ya bara la Ulaya, aina ya kukimbilia inayoendelea.</td></tr><tr><td>34</td><td>Njia ya Kuinua kwa Hatua Nne</td><td>Njia ya hatua nne ya kuinua kwa jumla ya ulimwengu wa Hengyuanzhou: msingi wa halisi → uwezo wa teknolojia → mageuzi ya fahari → simbiozi ya kati ya nyota.</td></tr><tr><td>35</td><td>Halisi kama Msingi</td><td>Moja ya misingi ya msingi ya Ustaarabu wa Simbiozi ya Nanga, inamaanisha kwamba ulimwengu halisi ndio ulimwengu wa kweli pekee, ulimwengu wa riwaya ni majaribio ya fikra za uongo, vitu vya kufikirika visivyotosheleza vinafadhiwa kwa halisi, na vitu visivyopo katika halisi vinatengenezwa kupitia kuinua kulingana na sheria.</td></tr><tr><td>36</td><td>Kiwango cha Simbiozi</td><td>Kiwango cha kiasi cha kutathmini kiwango cha ujumuishaji wa ustaarabu au mtu binafsi na mtandao wa simbiozi, kinajumuisha vipengele vingi kama vile kiwango cha kushiriki rasilimali, masafa ya ushirikiano, na uwiano wa tabia za kufaa wengine.</td></tr><tr><td>37</td><td>Baraza la Nanga</td><td>Shirika la nguvu za juu zaidi za Ustaarabu wa Simbiozi ya Nanga, linajumuisha uwakilishi wa kila jamii kulingana na uwiano, na linautumikia haki ya kutoa sheria na haki ya kuamua masuala muhimu.</td></tr><tr><td>38</td><td>Kamati ya Utekelezaji wa Simbiozi</td><td>Shirika la utawala la juu zaidi la Ustaarabu wa Simbiozi ya Nanga, linawajibika kwa utekelezaji wa katiba na sheria, na utawala wa kila siku.</td></tr><tr><td>39</td><td>Korti ya Simbiozi</td><td>Shirika la haki la juu zaidi la Ustaarabu wa Simbiozi ya Nanga, linautumikia haki ya hukumu kwa uhuru, na linawajibika kwa uchunguzi wa katiba na hukumu ya kesi muhimu.</td></tr><tr><td>40</td><td>Ofisi ya Usimamizi wa Ndege</td><td>Shirika maalum chini ya Baraza la Nanga, linawajibika kwa utunzaji wa benki ya jumla ya kuratibu wa ndege, uthibitisho wa idhini ya kupita, usimamizi wa uchunguzi wa kale wa kati ya ndege, na masuala mengine.</td></tr></tbody></table><h2 id="_3-kanuni-za-matumizi-ya-neno" tabindex="-1">3. Kanuni za Matumizi ya Neno <a class="header-anchor" href="#_3-kanuni-za-matumizi-ya-neno" aria-label="Permalink to &quot;3. Kanuni za Matumizi ya Neno&quot;">​</a></h2><ol><li>Maneno yaliyojumlishwa katika kamusi hii ni maneno ya kiwango, na hati zote zinapaswa kutoa kipaumbele kwa matumizi ya usemi wa kiwango katika kamusi hii.</li><li>Dhana moja lazima itumie neno moja katika hati tofauti, na haifai kubadilisha maneno sawa kwa hiari.</li><li>Maneno mapya yanayotokea katika usanidi mpya yanapaswa kuwasilishwa kwa wakati kamati ya neno kwa ajili ya uchunguzi, na baada ya kupita uchunguzi yatongezwa katika kamusi hii.</li><li>Ikiwa ufafanuzi wa neno umebadilishwa, toleo jipya zaidi za kamusi hii ndio litakuwa kiwango, na wakati huo huo maudhui ya marekebisho yanapaswa kuandikwa katika maelezo ya toleo la hati.</li><li>Wakati wa kunukuu neno, jina kamili linaweza kutumika kwa mara ya kwanza, na baadaye jina fupi linaweza kutumika, lakini lazima uhakikishe kuwa maana katika muktadha ni wazi.</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kamusi ya neno ni msingi wa lugha wa mfumo wote wa usanidi. Mfumo wa neno uliounganishwa unahakikisha uwiano wa dhana kati ya hati mia, na kuruhusu wasomaji kubadilisha kwa usalama kati ya moduli tofauti bila utata wa ufahamu. Kadiri mfumo wa usanidi unavyoendelea kuwa tajiri na kuboreshwa, kamusi hii itaendelea kusasishwa, na itabaki daima kama chanzo cha mamlaka cha neno kwa hati zote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>00-Maelezo ya Jumla ya Ulimwengu wa Hengyuanzhou</li><li>02-Ufafanuzi na Asili ya Asili ya Nanga</li><li>99-Maelezo ya Toleo na Utunzaji wa Hati</li></ul>',12)])])}const y=i(e,[["render",k]]);export{l as __pageData,y as default};
